fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut max_streak = 1;
    let mut current_streak = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            // Continue the increasing streak
            current_streak += 1;
            if current_streak > max_streak {
                max_streak = current_streak;
            }
        } else {
            // Reset the streak length
            current_streak = 1;
        }
    }

    max_streak
}